INSERT INTO `ai_model_provider` (`id`, `model_type`, `provider_code`, `name`, `fields`, `sort`, `creator`, `create_date`, `updater`, `update_date`) VALUES
('SYSTEM_TTS_doubao_v3', 'TTS', 'doubao_v3', '豆包语音合成v3', '[{"key":"appid","label":"应用ID","type":"string"},{"key":"access_token","label":"访问令牌","type":"password"},{"key":"api_key","label":"API Key(新版备用)","type":"password"},{"key":"resource_id","label":"资源ID","type":"string"},{"key":"api_url","label":"服务地址","type":"string"},{"key":"speaker","label":"默认音色","type":"string"},{"key":"voice_instruction","label":"语气指令(2.0音色)","type":"string"},{"key":"format","label":"音频格式","type":"string"},{"key":"sample_rate","label":"采样率","type":"number"},{"key":"speech_rate","label":"语速(-50~100)","type":"number"},{"key":"loudness_rate","label":"音量(-50~100)","type":"number"},{"key":"output_dir","label":"输出目录","type":"string"}]', 22, 1, NOW(), 1, NOW());
INSERT INTO `ai_model_config` (`id`, `model_type`, `model_code`, `model_name`, `is_default`, `is_enabled`, `config_json`, `doc_link`, `remark`, `sort`, `creator`, `create_date`, `updater`, `update_date`) VALUES
('TTS_DoubaoV3', 'TTS', 'DoubaoV3', '豆包语音合成v3(HTTP)', 0, 1, '{"type": "doubao_v3", "appid": "2717008086", "access_token": "W6P9P9w4FNK9qtTWHTQlokkmFRm-GZCa", "api_key": "d9f77dba-01ca-47fa-a4d3-7002adf6b6a4", "resource_id": "seed-tts-2.0", "api_url": "https://openspeech.bytedance.com/api/v3/tts/unidirectional", "speaker": "zh_female_xiaohe_uranus_bigtts", "voice_instruction": "像豆包AI助手一样说话，活泼元气，亲切自然，轻快俏皮，吐字清晰，用标准大陆普通话，不要台湾腔", "format": "wav", "sample_rate": 24000, "speech_rate": 0, "loudness_rate": 0, "output_dir": "tmp/"}', 'https://www.volcengine.com/docs/6561/1329505', '豆包语音合成大模型 v3 HTTP 一次性合成端点。\n1. 鉴权默认走旧版双头（应用ID+访问令牌），api_key 为新版控制台备用\n2. SecretKey 仅用于控制台签名场景，本端点无需填写\n3. 音色在音色管理中选择，语速/音量范围[-50,100]', 28, NULL, NULL, NULL, NULL);
